css:
.resume{max-width: 820px;
      width: 100%;
      background: #ffffff;
      box-shadow: 0 12px 30px rgba(0, 0, 0, 0.08), 0 4px 10px rgba(0, 0, 0, 0.02);
      border-radius: 0; 
      transition: all 0.2s;
      display: flex;
      flex-direction: column;}
.resume-layout{display: flex;
      flex-wrap: wrap;
      min-height: 100%;}
.accent-bar{width: 10px;
      background: #1e3b4f; 
      flex-shrink: 0;}
.main-content{flex: 1;
      padding: 2rem 2.2rem 2rem 2rem;
      background: white;
      display: flex;
      flex-direction: column;}
.resume h1, .resume h2, .resume h3, .resume p, .resume div, .resume span, .resume li{color: #2d3748;}
.name-section{margin-bottom: 1.25rem;
      border-bottom: 1.5px solid #cbd5e0;
      padding-bottom: 1.2rem;
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      justify-content: space-between;}
.name-title{display: flex;
      flex-direction: column;}
.name{font-size: 2.8rem;
      font-weight: 700;
      letter-spacing: 1px;
      line-height: 1.1;
      color: #1a202c;
      font-family: 'Helvetica Neue', 'Arial', '思源黑体', sans-serif;}
.subtitle{font-size: 1.1rem;
      font-weight: 400;
      color: #4a5568;
      margin-top: 0.25rem;
      font-style: normal;
      letter-spacing: 0.3px;}
.contact-info{display: flex;
      flex-wrap: wrap;
      gap: 1.2rem;
      align-items: center;
      color: #2d3748;
      font-size: 0.9rem;
      font-weight: 400;
      margin-top: 0.5rem;}
.contact-item{display: flex;
      align-items: center;
      gap: 0.3rem;
      white-space: nowrap;}
.icon{font-size: 1rem;
      color: #2c5f2d; 
      font-weight: 500;
      margin-right: 2px;}
.resume hr{border: 0;
      height: 1px;
      background: #e2e8f0;
      margin: 1.2rem 0 1.4rem 0;}
.section-title{font-size: 1rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: #1e3b4f;
      margin-bottom: 1rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;}
.section-title::after{content: "";
      flex: 1;
      height: 1px;
      background: #cbd5e0;
      margin-left: 0.5rem;}
.experience-item{margin-bottom: 1.4rem;}
.exp-header{display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: baseline;
      margin-bottom: 0.25rem;}
.company{font-weight: 700;
      font-size: 1.05rem;
      color: #1a202c;
      letter-spacing: -0.2px;}
.role{font-weight: 600;
      font-size: 0.95rem;
      color: #2d3748;
      margin-left: 0.2rem;}
.date{font-weight: 400;
      font-size: 0.85rem;
      color: #4a5568;
      background: transparent;
      white-space: nowrap;}
.exp-details{margin-top: 0.5rem;
      padding-left: 0.25rem;}
.exp-details ul{list-style: none;
      padding-left: 0;
      margin: 0;}
.exp-details li{font-size: 0.9rem;
      line-height: 1.5;
      margin-bottom: 0.4rem;
      display: flex;
      align-items: flex-start;
      gap: 0.5rem;
      color: #2d3748;}
.bullet{display: inline-block;
      width: 6px;
      height: 6px;
      background-color: #2c5f2d; 
      border-radius: 50%;
      margin-top: 0.55rem;
      flex-shrink: 0;}
.skills-container{display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
      margin-top: 0.3rem;}
.skill-tag{background: transparent;
      border: 1px solid #cbd5e0;
      color: #2d3748;
      padding: 0.3rem 1rem;
      font-size: 0.8rem;
      font-weight: 500;
      letter-spacing: 0.2px;
      border-radius: 30px;
      background: #ffffff;
      transition: none;
      white-space: nowrap;}
.education-item{display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: baseline;
      margin-bottom: 0.5rem;}
.school{font-weight: 700;
      color: #1a202c;}
.degree{font-weight: 500;
      color: #2d3748;
      margin-left: 0.3rem;}
.project-item{margin-bottom: 1rem;}
.project-title{font-weight: 700;
      font-size: 0.95rem;
      color: #1a202c;}
.project-desc{font-size: 0.88rem;
      color: #2d3748;
      margin-top: 0.2rem;
      padding-left: 0.5rem;
      border-left: 2px solid #cbd5e0;}
.two-columns{display: flex;
      flex-wrap: wrap;
      gap: 2rem;
      margin-top: 0.2rem;}
.col{flex: 1 1 180px;}.summary{font-size:0.9rem;line-height:1.6;margin-bottom:0.25rem;color:#2d3748}.skill-group{margin-bottom:0.8rem}.skill-group-label{font-weight:700;font-size:0.9rem;margin-bottom:0.4rem}.misc-line{display:flex;flex-wrap:wrap;gap:2rem;font-size:0.85rem;color:#2d3748;border-top:1px solid #e2e8f0;padding-top:0.8rem;margin-top:1rem}.misc-line strong{color:#1e3b4f}.lang{margin-right:8px}
